import {Text,View,type ViewProps} from "react-native";
import {joinClasses} from "@/components/nyc-tron/ui/components/styles";
import {useLocalStore} from "@/components/nyc-tron/ui/components/useLocalStore";
import {rgbaToHex} from "@/components/nyc-tron/ui/components/forge/color";
import {guideRect,safeAreas,type OverlayRect,type SafeAreaSpec} from "@/components/nyc-tron/ui/components/forge/timeline/safe-area";

// A letterbox matte is black by definition, in any theme; it is a picture value, not a UI color.
const MATTE=rgbaToHex({r:0,g:0,b:0,alpha:1},false);

/** Props for {@linkcode SafeAreaOverlay}. */
export interface SafeAreaOverlayProps extends Omit<ViewProps,"children"> {
  /** The picture's aspect ratio (width / height), e.g. 16 / 9. */
  readonly aspect:number;
  /** @default "smpte" (action 93%, title 90%) */
  readonly safeArea?:SafeAreaSpec;
  /** Draws action- and title-safe boxes. @default true */
  readonly showSafeAreas?:boolean;
  /** Framing guides to mask to, as width / height (e.g. FRAME_GUIDES.scope). The area outside is dimmed. */
  readonly guide?:number;
  /** Center cross. @default false */
  readonly showCenter?:boolean;
  /** Rule-of-thirds lines. @default false */
  readonly showThirds?:boolean;
  className?:string;
  unstyled?:boolean;
}

const box=(r:OverlayRect)=>({position:"absolute" as const,left:r.x,top:r.y,width:r.width,height:r.height});

/**
 * Guides over a video monitor (D-25): action- and title-safe boxes, an
 * aspect-ratio framing mask, a center cross and thirds. Lay it over the
 * monitor at the same size; it fits the picture by `aspect` (letterbox or
 * pillarbox) and never takes touches. Purely visual, so it is hidden from
 * screen readers; describe active guides in the monitor's own label.
 */
export function SafeAreaOverlay({
  aspect,safeArea="smpte",showSafeAreas=true,guide,showCenter=false,showThirds=false,className,unstyled=false,testID,style,...rest
}:SafeAreaOverlayProps){
  const initial=safeAreas({width:0,height:0},aspect,safeArea);if(guide!==undefined)guideRect(initial.picture,guide);
  const [size,store]=useLocalStore(()=>({width:0,height:0}));
  const styled=!unstyled;
  const areas=size.width>0?safeAreas(size,aspect,safeArea):undefined;
  const framed=areas&&guide!==undefined?guideRect(areas.picture,guide):undefined;
  const line=joinClasses(styled&&"border-text-muted");
  const label=joinClasses(styled&&"text-text-muted text-xs");
  const pct=(n:number)=>Math.round(n*100)+"%";
  const masks=areas&&framed?[
    {x:areas.picture.x,y:areas.picture.y,width:areas.picture.width,height:framed.y-areas.picture.y},
    {x:areas.picture.x,y:framed.y+framed.height,width:areas.picture.width,height:areas.picture.y+areas.picture.height-framed.y-framed.height},
    {x:areas.picture.x,y:framed.y,width:framed.x-areas.picture.x,height:framed.height},
    {x:framed.x+framed.width,y:framed.y,width:areas.picture.x+areas.picture.width-framed.x-framed.width,height:framed.height},
  ].filter(r=>r.width>0.5&&r.height>0.5):[];
  return <View {...rest} {...(testID?{testID}:{})} pointerEvents="none"
    accessibilityElementsHidden importantForAccessibility="no-hide-descendants" aria-hidden
    onLayout={e=>{const {width,height}=e.nativeEvent.layout;if([width,height].every(Number.isFinite)&&width>=0&&height>=0)store.set({width,height});}}
    {...{className:joinClasses(className)}} style={[{position:"absolute",left:0,top:0,right:0,bottom:0,direction:"ltr"},style]}>
    {masks.map((r,i)=><View key={"m"+i} style={{...box(r),backgroundColor:MATTE,opacity:0.6}}/>)}
    {framed?<View {...{className:line}} style={{...box(framed),borderWidth:1}}/>:null}
    {areas&&showSafeAreas?<>
      <View {...{className:line}} style={{...box(areas.action),borderWidth:1,borderStyle:"dashed"}}>
        <Text {...{className:label}} style={{position:"absolute",left:4,top:2}}>{`Action safe ${pct(areas.fractions.action)}`}</Text>
      </View>
      <View {...{className:line}} style={{...box(areas.title),borderWidth:1}}>
        <Text {...{className:label}} style={{position:"absolute",right:4,bottom:2}}>{`Title safe ${pct(areas.fractions.title)}`}</Text>
      </View>
    </>:null}
    {areas&&showThirds?[1,2].flatMap(k=>[
      <View key={"v"+k} {...{className:line}} style={{position:"absolute",left:areas.picture.x+areas.picture.width*k/3,top:areas.picture.y,height:areas.picture.height,borderLeftWidth:1,opacity:0.6}}/>,
      <View key={"h"+k} {...{className:line}} style={{position:"absolute",top:areas.picture.y+areas.picture.height*k/3,left:areas.picture.x,width:areas.picture.width,borderTopWidth:1,opacity:0.6}}/>,
    ]):null}
    {areas&&showCenter?<>
      <View {...{className:line}} style={{position:"absolute",left:areas.picture.x+areas.picture.width/2-10,top:areas.picture.y+areas.picture.height/2,width:20,borderTopWidth:1}}/>
      <View {...{className:line}} style={{position:"absolute",top:areas.picture.y+areas.picture.height/2-10,left:areas.picture.x+areas.picture.width/2,height:20,borderLeftWidth:1}}/>
    </>:null}
  </View>;
}

import {createStore} from "zustand/vanilla";

/**
 * A per-instance store for transient gesture and draft state (a drag preview, a
 * text draft, a measured width). Components use it instead of `useState` so a
 * gesture's bookkeeping lives outside React's render cycle and can be read
 * synchronously from responder callbacks. Created by {@linkcode createLocalStore};
 * components use it through `useLocalStore`. Zustand owns the state; this value-replacement
 * adapter remains independent of React.
 */
export interface LocalStore<T> {
  get():T;
  /** Replaces the state, or derives it from the previous state. Listeners run only when it changes. */
  set(next:T|((previous:T)=>T)):void;
  /** Returns the unsubscribe function. */
  subscribe(listener:()=>void):()=>void;
}

/** Creates a {@linkcode LocalStore}. Equal states (by `Object.is`) do not notify. */
export function createLocalStore<T>(initial:T):LocalStore<T>{
  const store=createStore<{value:T}>(()=>({value:initial}));
  return {
    get:()=>store.getState().value,
    set(next){
      store.setState(current=>{
        const value=typeof next==="function"?(next as (p:T)=>T)(current.value):next;
        return Object.is(value,current.value)?current:{value};
      });
    },
    subscribe(listener){return store.subscribe(()=>listener());},
  };
}

/**
 * Tailwind classes are merged at the APP boundary. Joining without
 * tailwind-merge avoids deleting custom typography/color utilities that
 * depend on each consumer's own @theme configuration.
 */
export function joinClasses(...items: Array<string|false|null|undefined>):string {
  return items.filter(Boolean).join(" ");
}

import {useRef,useSyncExternalStore} from "react";
import {createLocalStore,type LocalStore} from "@/components/nyc-tron/ui/components/local-store";

/**
 * Creates one {@linkcode LocalStore} for the calling component on first render and
 * subscribes to it. Returns the current state and the store.
 */
export function useLocalStore<T>(initial:()=>T):readonly [T,LocalStore<T>]{
  const ref=useRef<LocalStore<T>|null>(null);
  if(!ref.current)ref.current=createLocalStore(initial());
  const store=ref.current;
  const state=useSyncExternalStore(store.subscribe,store.get,store.get);
  return [state,store] as const;
}
